const replaceChapterCard = `-- name: ReplaceChapterCard :one
INSERT INTO chapter_cards (project_id, chapter_id, content_hash, card_json, model, version)
VALUES ($1, $2, $3::bytea, $4::jsonb,
  $5::text, $6::integer)
ON CONFLICT (project_id, chapter_id, content_hash) DO UPDATE
SET card_json = EXCLUDED.card_json, model = EXCLUDED.model, version = EXCLUDED.version,
    built_from = NULL, created_at = clock_timestamp()
RETURNING (xmax = 0) AS inserted
`

type ReplaceChapterCardParams struct {
	ProjectID   pgtype.UUID `json:"project_id"`
	ChapterID   pgtype.UUID `json:"chapter_id"`
	ContentHash []byte      `json:"content_hash"`
	CardJson    []byte      `json:"card_json"`
	Model       string      `json:"model"`
	Version     int32       `json:"version"`
}

// The operator's load writes a card built elsewhere over the card of the same text, whatever
// model wrote it; inserted is false when a card was replaced.
func (q *Queries) ReplaceChapterCard(ctx context.Context, arg ReplaceChapterCardParams) (bool, error) {
	row := q.db.QueryRow(ctx, replaceChapterCard,
		arg.ProjectID,
		arg.ChapterID,
		arg.ContentHash,
		arg.CardJson,
		arg.Model,
		arg.Version,
	)
	var inserted bool
	err := row.Scan(&inserted)
	return inserted, err
}

